mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM generic_master request_type_master
    INNER JOIN generic_master_values request_type
        ON request_type.generic_master_id = request_type_master.id
        AND request_type.company_id = #{companyId}
    WHERE request_type_master.code = 'REQUEST_TYPE'
        AND request_type_master.is_deleted = FALSE
        AND request_type.code = #{code}
)

mapper.update:
UPDATE generic_master_values request_type
INNER JOIN generic_master request_type_master
    ON request_type_master.id = request_type.generic_master_id
    AND request_type_master.code = 'REQUEST_TYPE'
    AND request_type_master.is_deleted = FALSE
SET request_type.is_deleted = TRUE,
    request_type.updated_by = #{updatedBy}
WHERE request_type.id = #{id}
    AND request_type.company_id = #{companyId}
    AND request_type.is_deleted = FALSE

UPDATE generic_master_values request_type
INNER JOIN generic_master request_type_master
    ON request_type_master.id = request_type.generic_master_id
    AND request_type_master.code = 'REQUEST_TYPE'
    AND request_type_master.is_deleted = FALSE
SET request_type.is_deleted = FALSE,
    request_type.updated_by = #{updatedBy}
WHERE request_type.id = #{id}
    AND request_type.company_id = #{companyId}
    AND request_type.is_deleted = TRUE
